entries[14630] = { ["name"] = "Pattern: Enchanter's Cowl", ["text"] = "Requires Tailoring (165)\n\nUse: Teaches you how to sew an Enchanter's Cowl.\nSell Price:\nEnchanter's Cowl\nBinds when equipped\nHead Cloth\n37 Armor\n+10 Intellect\n+6 Spirit\nDurability 45 / 45\nRequires Level 28\nSell Price:\nRequires Bolt of Silk Cloth (3), Fine Thread (2), Thick Spider's Silk (2)" }
entries[14634] = { ["name"] = "Recipe: Frost Oil", ["text"] = "Requires Alchemy (200)\n\nUse: Teaches you how to make Frost Oil.\nSell Price:\nFrost Oil\nRequires Level 30\n\nUse: When applied to a melee weapon it gives a 10% chance of casting Frostbolt at the opponent when it hits. Lasts 30 minutes.\nSell Price:\nRequires Khadgar's Whisker (4), Wintersbite (2), Leaded Vial" }
entries[14635] = { ["name"] = "Pattern: Gem-studded Leather Belt", ["text"] = "Requires Leatherworking (185)\n\nUse: Teaches you how to craft a Gem-studded Leather Belt.\nSell Price:\nGem-studded Leather Belt\nBinds when equipped\nWaist Leather\n65 Armor\n+8 Stamina\n+6 Spirit\nDurability 35 / 35\nRequires Level 32\nUse: Heal yourself for 225 to 375. (1 Hour Cooldown)\nSell Price:\nRequires Cured Heavy Hide (4), Iridescent Pearl (2), Jade (2), Citrine , Fine Thread" }
entries[14639] = { ["name"] = "Schematic: Minor Recombobulator", ["text"] = "Requires Engineering (140)\n\nUse: Teaches you how to make a Minor Recombobulator.\nSell Price:\nMinor Recombobulator\nTrinket\nRequires Engineering (140)\nUse: Dispels Polymorph effects on a friendly target. Also restores 150 to 250 health and mana. (5 Min Cooldown)\n10 Charges\nSell Price:\nRequires Bronze Tube , Whirring Bronze Gizmo (2), Medium Leather (2), Moss Agate" }
